function escapeHtml(text) {
  const map = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };
  return String(text).replace(/[&<>"']/g, (ch) => map[ch]);
}

tests.code:
assertEqual(escapeHtml("a < b"), "a &lt; b", "must not become &amp;lt;");
assertEqual(escapeHtml("plain text 123"), "plain text 123", "unchanged");
assertEqual(escapeHtml(42), "42", "numbers become strings");

