coding.solution:
function isAllowedFetchUrl(url, allowedHosts) {
  let parsed;
  try {
    parsed = new URL(url);
  } catch (err) {
    return false;
  }
  if (typeof url !== "string") return false;
  if (parsed.protocol !== "https:") return false;
  if (parsed.username !== "" || parsed.password !== "") return false;
  const allowed = allowedHosts.map((host) => host.toLowerCase());
  return allowed.includes(parsed.hostname.toLowerCase());
}

tests.code:
const hosts = ["images.example.com", "cdn.example.org"];
assertEqual(isAllowedFetchUrl("https://images.example.com/a.png", hosts), true, "first host");
assertEqual(isAllowedFetchUrl("https://CDN.Example.org/pic.jpg?size=2", hosts), true, "case-insensitive host");

const hosts = ["images.example.com"];
assertEqual(isAllowedFetchUrl("https://localhost/admin", hosts), false, "localhost");
assertEqual(isAllowedFetchUrl("https://169.254.169.254/latest/meta-data", hosts), false, "link-local address");
assertEqual(isAllowedFetchUrl("https://images.example.com/ok.png", hosts), true, "listed host still allowed");

const hosts = ["images.example.com"];
assertEqual(isAllowedFetchUrl("https://images.example.com.evil.test/a.png", hosts), false, "allowed name as a prefix");
assertEqual(isAllowedFetchUrl("https://evil.test/images.example.com", hosts), false, "allowed name in the path");
assertEqual(isAllowedFetchUrl("https://images.example.com@127.0.0.1/a.png", hosts), false, "allowed name in the username part");
assertEqual(isAllowedFetchUrl("https://images.example.com/a.png", hosts), true, "genuine URL");

const hosts = ["images.example.com"];
assertEqual(isAllowedFetchUrl("http://images.example.com/a.png", hosts), false, "plain http");
assertEqual(isAllowedFetchUrl("file:///etc/passwd", hosts), false, "file protocol");
assertEqual(isAllowedFetchUrl("not a url", hosts), false, "unparsable");
assertEqual(isAllowedFetchUrl(null, hosts), false, "null");
assertEqual(isAllowedFetchUrl("https://images.example.com/", hosts), true, "genuine URL");

