coding.solution:
async function settleOrder(checkPayment, timeoutMs) {
  const timeout = new Promise((resolve) => setTimeout(() => resolve({ status: "timeout" }), timeoutMs));
  let result;
  try {
    result = await Promise.race([checkPayment(), timeout]);
  } catch (err) {
    return "pending";
  }
  if (result && result.status === "approved") return "paid";
  if (result && result.status === "declined") return "declined";
  return "pending";
}

tests.code:
assertEqual(await settleOrder(async () => null, 50), "pending", "null");
assertEqual(await settleOrder(async () => ({}), 50), "pending", "no status");
assertEqual(await settleOrder(async () => ({ status: "APPROVED?" }), 50), "pending", "unknown status");
assertEqual(await settleOrder(async () => ({ status: true }), 50), "pending", "wrong type");
